import React, { useState } from "react";
import "./App.css";
import { useEmpleados } from "./hooks/useEmpleados";
import { usePeriodos } from "./hooks/usePeriodos";
import { usePlanillas } from "./hooks/usePlanillas";
import Navbar from "./components/Navbar";
import Home from "./pages/Home";
import Empleados from "./pages/Empleados";
import Periodos from "./pages/Periodos";
import Planillas from "./pages/Planillas";
import PlanillaMensual from "./pages/PlanillaMensual";
import DetallePlanilla from "./components/DetallePlanilla";

function App() {
  const [vista, setVista] = useState("home");

  // Estado para la planilla mensual
  const [periodoSeleccionado, setPeriodoSeleccionado] = useState(null);

  // Hooks
  const empleadosHook = useEmpleados();
  const periodosHook = usePeriodos();
  const planillasHook = usePlanillas();

  // Limpiar formularios al cambiar de vista
  const limpiarFormularios = () => {
    empleadosHook.limpiarFormularioEmpleado();
    periodosHook.limpiarFormularioPeriodo();
    planillasHook.limpiarFormularioPlanilla();
  };

  // Ver detalle desde la planilla mensual
  const verDetalleDesdeMensual = (planillaId) => {
    const pl = planillasHook.planillas.find(p => p.id === planillaId);
    if (pl) {
      planillasHook.verDetalle(pl);
      setVista("planillas");
    }
  };

  // Renderizar contenido según la vista
  const renderContent = () => {
    if (planillasHook.vistaDetalle) {
      return (
        <DetallePlanilla
          planilla={planillasHook.planillaSeleccionada}
          empleados={empleadosHook.empleados}
          periodos={periodosHook.periodos}
          onVolver={() => {
            planillasHook.volverAListado();
            setVista("planillas");
          }}
        />
      );
    }

    switch (vista) {
      case "home":
        return <Home />;
      case "empleados":
        return (
          <Empleados
            empleados={empleadosHook.empleados}
            nuevoEmpleado={empleadosHook.nuevoEmpleado}
            setNuevoEmpleado={empleadosHook.setNuevoEmpleado}
            empleadoCargado={empleadosHook.empleadoCargado}
            filtroEmpleados={empleadosHook.filtroEmpleados}
            setFiltroEmpleados={empleadosHook.setFiltroEmpleados}
            crearEmpleado={empleadosHook.crearEmpleado}
            actualizarEmpleado={empleadosHook.actualizarEmpleado}
            cargarEmpleado={empleadosHook.cargarEmpleado}
            eliminarEmpleado={empleadosHook.eliminarEmpleado}
            limpiarFormularioEmpleado={empleadosHook.limpiarFormularioEmpleado}
          />
        );
      case "periodos":
        return (
          <Periodos
            periodos={periodosHook.periodos}
            nuevoPeriodo={periodosHook.nuevoPeriodo}
            setNuevoPeriodo={periodosHook.setNuevoPeriodo}
            periodoCargado={periodosHook.periodoCargado}
            crearPeriodo={periodosHook.crearPeriodo}
            eliminarPeriodo={periodosHook.eliminarPeriodo}
            cargarPeriodo={periodosHook.cargarPeriodo}
            limpiarFormularioPeriodo={periodosHook.limpiarFormularioPeriodo}
            generarProximoPeriodo={periodosHook.generarProximoPeriodo}
          />
        );
      case "planillas":
        return (
          <Planillas
            planillas={planillasHook.planillas}
            nuevaPlanilla={planillasHook.nuevaPlanilla}
            setNuevaPlanilla={planillasHook.setNuevaPlanilla}
            planillaCargado={planillasHook.planillaCargado}
            crearPlanilla={planillasHook.crearPlanilla}
            actualizarPlanilla={planillasHook.actualizarPlanilla}
            eliminarPlanilla={planillasHook.eliminarPlanilla}
            cargarPlanilla={planillasHook.cargarPlanilla}
            limpiarFormularioPlanilla={planillasHook.limpiarFormularioPlanilla}
            empleados={empleadosHook.empleados}
            periodos={periodosHook.periodos}
            onVerDetalle={planillasHook.verDetalle}
          />
        );
      case "planillaMensual":
        return (
          <PlanillaMensual
            periodos={periodosHook.periodos}
            empleados={empleadosHook.empleados}
            planillas={planillasHook.planillas}
            periodoSeleccionado={periodoSeleccionado}
            setPeriodoSeleccionado={setPeriodoSeleccionado}
            onVerDetalle={verDetalleDesdeMensual}
          />
        );
      default:
        return <Home />;
    }
  };

  return (
    <div className="app">
      <Navbar
        vista={vista}
        setVista={(v) => {
          setVista(v);
          if (v !== "planillaMensual") setPeriodoSeleccionado(null);
          limpiarFormularios();
        }}
      />
      <div className="content">{renderContent()}</div>
      <footer className="footer">
        © 2026 Texaco El Salvador - Sistema de Control de Planillas
      </footer>
    </div>
  );
}

export default App;
